type GenericRepository[T schema.Tabler] struct {
	db    *gorm.DB
	model T
}

func (repo GenericRepository[T]) FindOneByIDSelection(
	ctx context.Context,
	entity interface{},
	id interface{},
) error {
	selection, err := repo.extractSelection(entity)
	if err != nil {
		return err
	}

	return repo.db.WithContext(ctx).
		Table(repo.model.TableName()).
		Select(selection).
		First(entity, "id = ?", id).Error
}

type BaseRepository interface {
	SetupConnection(db *gorm.DB)
}

type DBTransaction struct {
	db    *gorm.DB
	repos []BaseRepository
}

func (main *DBTransaction) Begin() {
	tx := main.db.Begin()
	for _, rp := range main.repos {
		rp.SetupConnection(tx)
	}
	main.db = tx
}

func (main *DBTransaction) End(err error) error {
	if err != nil {
		if errTrx := main.db.Rollback().Error; errTrx != nil {
			return errTrx
		}
		return nil
	}
	return main.db.Commit().Error
}

type InvalidDataError struct {
	Msg             string
	DataToTemplated map[string]string
}
func (e InvalidDataError) Error() string { return e.Msg }

func (m Mapper) NewResponse(c *gin.Context, res *payload.Response, err error) {
	userData := m.GetAuthDataFromContext(c)
	if err != nil {
		if ok, invErr := m.IsInvalidDataError(err); ok {
			c.JSON(http.StatusBadRequest, payload.DefaultErrorInvalidDataWithMessage(m.localizer.GetLocalized(userData.Lang, err.Error())))
			return
		}
		c.JSON(http.StatusInternalServerError, payload.DefaultErrorResponseWithMessage(m.localizer.GetLocalized(userData.Lang, "InternalError"), err))
		return
	}
	c.JSON(http.StatusOK, res)
}

func (receiver Auth) Authorize(roles ...string) gin.HandlerFunc {
	return func(c *gin.Context) {
		var authData = payload.UserData{}
		if authDataStr, ok := c.Get("authData"); ok {
			authData = authDataStr.(payload.UserData)
		}
		if slices.Contains(roles, authData.RoleName) {
			c.Next()
			return
		}
		c.JSON(http.StatusUnauthorized, payload.DefaultBadRequestResponse())
		c.Abort()
	}
}
